      assert.equal("coverage" in receipt, false);
      results.push(output);
    runtime,
    /CARGO_TERM_COLOR: always|RUST_TEST_THREADS: ''/u,
  );
  assert.match(runtime, /cargo test --workspace --doc --locked/u);
});

